(function(){
const root=document.querySelector('#classroom-root'),plans=window.MatematikONClassroomPlans||{},id=new URLSearchParams(location.search).get('id'),plan=plans[id];
let current=0;
const tr=(value,script)=>Array.isArray(value)?value[script==='latn'?0:1]:value;
const labels={latn:{back:'← Nazad na lekciju',area:'Pregled oblasti',goals:'Ciljevi časa',minutes:'min',stage:'Deo',previous:'← Prethodno',next:'Sledeće →',nextExample:'Sledeći primer',finish:'Završi čas',fullscreen:'Ceo ekran',exit:'Izađi iz celog ekrana',check:'Proveri',correct:'Tačno!',wrong:'Nije tačno. Pokušaj ponovo.',restart:'Ponovi aktivnost'},cyrl:{back:'← Назад на лекцију',area:'Преглед области',goals:'Циљеви часа',minutes:'мин',stage:'Део',previous:'← Претходно',next:'Следеће →',nextExample:'Следећи пример',finish:'Заврши час',fullscreen:'Цео екран',exit:'Изађи из целог екрана',check:'Провери',correct:'Тачно!',wrong:'Није тачно. Покушај поново.',restart:'Понови активност'}};
function script(){return window.getSiteScript?window.getSiteScript():'cyrl'}
function areaUrl(){return `/oblast.html?oblast=${encodeURIComponent(plan.area)}`}
function lessonUrl(){return `/lekcija.html?id=${encodeURIComponent(id)}`}
function mathHtml(value){const sup={'⁰':'0','¹':'1','²':'2','³':'3','⁴':'4','⁵':'5','⁶':'6','⁷':'7','⁸':'8','⁹':'9'},sub={'₀':'0','₁':'1','₂':'2','₃':'3','₄':'4','₅':'5','₆':'6','₇':'7','₈':'8','₉':'9'},frac=(a,b)=>`<span class="math-fraction"><span>${a}</span><span>${b}</span></span>`;return String(value).replace(/([⁰¹²³⁴⁵⁶⁷⁸⁹]+)⁄([₀₁₂₃₄₅₆₇₈₉]+)/g,(_,a,b)=>frac([...a].map(x=>sup[x]).join(''),[...b].map(x=>sub[x]).join(''))).replace(/\b(\d+)\/(\d+)\b/g,(_,a,b)=>frac(a,b))}
function activityMarkup(activity,s,l){if(!activity)return'';const question=mathHtml(tr(activity.question,s)),type=activity.type||'single';if(type==='number')return `<section class="touch-activity" data-touch-type="number"><h3>${question}</h3><div class="touch-number"><output data-touch-output aria-live="polite"></output><div class="touch-keypad">${['1','2','3','4','5','6','7','8','9',',','0','⌫'].map(k=>`<button type="button" data-key="${k}">${k}</button>`).join('')}</div><button type="button" class="touch-check" data-touch-check>${l.check}</button></div><p class="touch-feedback" aria-live="polite"></p><button type="button" class="touch-restart" data-touch-restart hidden>${l.restart}</button></section>`;const choices=tr(activity.choices,s);return `<section class="touch-activity" data-touch-type="${type}"><h3>${question}</h3><div class="touch-choices">${choices.map((x,i)=>`<button type="button" data-touch-choice="${i}">${mathHtml(x)}</button>`).join('')}</div>${type==='multi'?`<button type="button" class="touch-check" data-touch-check>${l.check}</button>`:''}<p class="touch-feedback" aria-live="polite"></p><button type="button" class="touch-restart" data-touch-restart hidden>${l.restart}</button></section>`}
function render(){
 const s=script(),l=labels[s];
 if(!plan){root.innerHTML=`<section class="classroom-error"><h1>${s==='latn'?'Čas nije pronađen':'Час није пронађен'}</h1><a href="/">${s==='latn'?'Početna':'Почетна'}</a></section>`;return}
 const item=plan.stages[current],percent=Math.round((current+1)/plan.stages.length*100);
 root.innerHTML=`<section class="classroom-shell"><div class="classroom-top"><div><a href="${lessonUrl()}" class="class-back">${l.back}</a><p>${l.stage} ${current+1} / ${plan.stages.length} · ${item.duration} ${l.minutes}</p><h1>${tr(plan.title,s)}</h1></div><div class="classroom-actions"><a href="${areaUrl()}">${l.area}</a><button type="button" data-fullscreen>${document.fullscreenElement?l.exit:l.fullscreen}</button></div></div><div class="classroom-progress" aria-label="${percent}%"><i style="width:${percent}%"></i></div><div class="classroom-layout"><aside><h2>${l.goals}</h2><ul>${tr(plan.goals,s).map(x=>`<li>${x}</li>`).join('')}</ul><nav class="stage-list" aria-label="${l.stage}">${plan.stages.map((x,i)=>`<button type="button" data-stage="${i}" class="${i===current?'active':''}"><b>${i+1}</b><span>${tr(x.label,s)}<small>${x.duration} ${l.minutes}</small></span></button>`).join('')}</nav></aside><article class="classroom-card"><header><span>${current+1}</span><div><small>${item.duration} ${l.minutes}</small><h2>${tr(item.label,s)}</h2></div></header><div class="classroom-content">${mathHtml(tr(item.content,s))}${activityMarkup(item.activity,s,l)}</div><footer><button type="button" data-prev ${current===0?'disabled':''}>${l.previous}</button><button type="button" class="primary" data-next>${current===plan.stages.length-1?l.finish:l.next}</button></footer></article></div></section>`;
 root.querySelectorAll('.class-answer summary').forEach(el=>el.textContent=s==='latn'?el.dataset.lat:el.dataset.cyrl);
 bind();document.title=`${tr(plan.title,s)} — MatematikON`;
}
function bindActivity(activity,l){if(!activity)return;const box=root.querySelector('.touch-activity'),feedback=box?.querySelector('.touch-feedback');if(!box)return;let selected=[];const finish=(ok,button)=>{feedback.textContent=ok?l.correct:l.wrong;feedback.className=`touch-feedback ${ok?'correct':'wrong'}`;if(ok){button?.classList.add('correct');box.querySelectorAll('[data-touch-choice],[data-key],[data-touch-check]').forEach(b=>b.disabled=true);box.querySelector('[data-touch-restart]').hidden=false}else button?.classList.add('wrong')};box.querySelectorAll('[data-touch-choice]').forEach(button=>button.addEventListener('click',()=>{const i=+button.dataset.touchChoice;if(activity.type==='multi'){button.classList.toggle('selected');selected=selected.includes(i)?selected.filter(x=>x!==i):[...selected,i];return}finish(i===activity.answer,button)}));if(activity.type==='multi')box.querySelector('[data-touch-check]')?.addEventListener('click',()=>finish([...activity.answer].sort().join(',')===[...selected].sort().join(',')));if(activity.type==='number'){let value='';const output=box.querySelector('[data-touch-output]');box.querySelectorAll('[data-key]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.key;if(key==='⌫')value=value.slice(0,-1);else if(key===','&&!value.includes(','))value+=key;else if(key!==',')value+=key;output.textContent=value}));box.querySelector('[data-touch-check]')?.addEventListener('click',()=>finish(Number(value.replace(',','.'))===Number(activity.answer)))}box.querySelector('[data-touch-restart]')?.addEventListener('click',render)}
function bindProgressiveExamples(l){if(current!==2)return;const list=root.querySelector('.classroom-content .class-tasks'),items=[...(list?.children||[])];if(items.length<2)return;items.slice(1).forEach(item=>item.hidden=true);const button=document.createElement('button');button.type='button';button.className='next-class-example';button.textContent=l.nextExample;list.insertAdjacentElement('afterend',button);button.addEventListener('click',()=>{const next=items.find(item=>item.hidden);if(next)next.hidden=false;if(!items.some(item=>item.hidden))button.hidden=true})}
function bind(){const item=plan?.stages[current],s=script(),l=labels[s];root.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{current=+b.dataset.stage;render()}));root.querySelector('[data-prev]')?.addEventListener('click',()=>{if(current>0){current--;render()}});root.querySelector('[data-next]')?.addEventListener('click',()=>{if(current<plan.stages.length-1){current++;render()}else location.href=lessonUrl()});root.querySelector('[data-fullscreen]')?.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){}render()});root.querySelectorAll('.class-step-solution [data-reveal]').forEach(button=>button.addEventListener('click',()=>{const steps=[...button.parentElement.querySelectorAll('[data-reveal-step]')],next=steps.find(x=>x.hidden);if(next)next.hidden=false;if(!steps.some(x=>x.hidden))button.hidden=true}));bindProgressiveExamples(l);bindActivity(item?.activity,l)}
window.renderRouteText=render;document.addEventListener('fullscreenchange',render);document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'&&plan&&current<plan.stages.length-1){current++;render()}if(e.key==='ArrowLeft'&&current>0){current--;render()}});render();
})();
